-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "koKR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "정령"
L["rm.era.shaman.elemental.Description"] = "10레벨부터의 정기 로테이션(정기에 특성 점수가 가장 많을 때)으로, Icy Veins와 Wowhead를 바탕으로 만들었습니다. 대지 충격으로 차단하고 곧 죽을 대상을 마무리합니다. 이동 중에는: 화염 충격, 없으면 냉기 충격. 혼자일 때 대상이 근접 거리에 있으면: 생명력 30% 이상에서 대지 충격, 그다음 근접 공격. 적이 셋 이상이면: 근접 거리에 있을 때 불꽃 회오리 토템과 용암 토템, 그리고 연쇄 번개. 정기의 깨달음이나 정신 집중 중에는 연쇄 번개, 그 외에는 번개 화살. 알림: 번개 보호막, 공격대 밖에서 대지의 무기, 불타는 토템 또는 용암 토템, 마나샘 토템 또는 치유의 토템, 연쇄 번개가 준비되었을 때 정기의 깨달음, 30% 미만에서 자연의 신속함과 치유의 물결, 전투 후 치유. 해제, 정화, 하위 등급 사용은 직접 판단합니다."
L["rm.era.shaman.elemental.simulator.Name"] = "정기, 재사용 대기시간마다 연쇄 번개 (시뮬레이터)"
L["rm.era.shaman.elemental.simulator.Description"] = "시뮬레이터의 정기 목록으로, 추천 정기 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 단일 대상에게도 재사용 대기시간마다 연쇄 번개, 정기의 깨달음이 걸려 있는 동안 대지 충격, 그 외에는 번개 화살. 추천 기본 제공 로테이션보다 빠르지만 마나를 훨씬 많이 쓰며, 차단, 토템, 알림은 같습니다."
L["rm.era.shaman.enhancement.Name"] = "고양"
L["rm.era.shaman.enhancement.Description"] = "1–60레벨용이며 하드코어와 자수성가 서버에서도 쓰이고, 특성 점수가 한쪽에 몰리지 않은 모든 주술사용입니다. Icy Veins, Wowhead, 시뮬레이터를 바탕으로 만들었습니다. 원거리에서 번개 화살로 끌어오고, 대지 충격으로 차단합니다. 공격대에서는 폭풍의 일격과 냉기 충격만 사용합니다(약화 효과 자리). 적이 셋 이상 나와 싸우면 불꽃 회오리 토템과 용암 토템. 그다음 폭풍의 일격, 폭풍의 일격 약화 효과에 맞추거나 마무리용으로 대지 충격, 끝까지 지속될 때 화염 충격, 마나가 절반 있는 동안 대지 충격, 닿지 않는 동안 번개 화살. 알림: 혼자일 때 대지의 무기, 던전에서 질풍의 무기, 번개 보호막, 대지력 토템, 불타는 토템, 질풍의 토템 또는 은총의 토템, 마나샘 토템 또는 치유의 토템, 전투 후와 위급할 때 치유. 돌발톱 토템, 속박의 토템, 토템 교체(트위스팅), 종족 특성은 꺼진 상태로 나열되며, 해제, 정화, 정화 토템은 직접 판단합니다."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "고양, 화염 충격 우선 (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Warcraft Tavern의 고양 로테이션으로, 추천 고양 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 배우는 즉시 질풍의 무기, 폭풍의 일격, 직접 피해 충격보다 먼저 화염 충격, 그다음 위협 수준이 낮은 동안 대지 충격, 그룹에서 위협 수준이 높아지면 냉기 충격; 무리에는 용암 토템과 연쇄 번개. 토템과 알림은 추천 기본 제공 로테이션과 같습니다."
L["rm.era.shaman.restoration.Name"] = "복원"
L["rm.era.shaman.restoration.Description"] = "10레벨부터의 복원 로테이션(복원에 특성 점수가 가장 많을 때)으로, Icy Veins와 Wowhead를 바탕으로 만들었습니다. 우호적 대상에게: 자연의 신속함 중에 치유의 물결, 30% 미만이면 자연의 신속함, 40% 미만이면 하급 치유의 물결, 해독 또는 질병 치료, 근처 그룹원 셋이 85% 미만이면 연쇄 치유, 그 외에는 90% 미만에서 치유의 물결. 싸우는 적에게는: 대지 충격 차단, 무리에 연쇄 번개, 화염 충격, 원거리에서 번개 화살, 근접 공격. 알림: 혼자일 때 번개 보호막과 대지의 무기, 그룹에서 마나 해일 토템, 마나샘 토템, 대지력 토템, 불타는 토템. 누구를 치유할지, 하위 등급 사용, 진동의 토템이나 정화 토템은 직접 판단하며, 방어 전담에게 치유의 길 유지는 꺼진 상태로 나열됩니다."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "복원, 연쇄 치유 우선 (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Warcraft Tavern의 복원 로테이션으로, 추천 복원 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 90% 미만인 누구에게나 연쇄 치유를 주 치유로 쓰고, 곧 죽을 사람에게는 하급 치유의 물결을 사용합니다. 치유의 물결은 치유의 길을 쓰며 방어 전담 치유를 배정받은 치유사용입니다(꺼진 상태로 나열). 치료, 적에게 주는 피해, 토템 알림은 추천 기본 제공 로테이션과 같습니다."
L["rm.forever.shaman.elemental.Name"] = "정령"
L["rm.forever.shaman.elemental.Description"] = "정기가 주 특성 트리이고 21포인트(용암 폭발 계층)를 투자한 뒤의 원거리 정기 로테이션으로, Icy Veins를 따릅니다(그 전에는 모든 공략이 권장하는 근접 하이브리드를 고양 기본 제공 로테이션이 맡습니다). 번개 화살(다수의 적에게는 연쇄 번개)로 끌어오고, 이동 중에는 즉시 시전 주문만 사용하며, 적이 셋 이상이면 불꽃 회오리와 연쇄 번개, 화염 충격 유지, 재사용 대기시간마다 용암 폭발, 폭풍의 일격을 알면 폭풍의 일격과 대지 충격, 그룹에서 번뜩임 발동 시 불꽃 회오리, 그다음 번개 화살을 사용합니다. 알림: 보호막, 무기 강화, 불타는 토템 또는 용암 토템, 그룹 토템, 정기의 깨달음, 차단. Forever에서는 생명력과 마나가 애드온에 숨겨져 있으므로 스스로 치유하는 것과 마나 회복을 위해 멈추는 것은 직접 판단합니다. 직접 판단할 것: 속박의 토템 카이팅, 냉기 충격, 정화, 다른 토템."
L["rm.forever.shaman.enhancement.Name"] = "고양 (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "1레벨부터 60레벨까지의 근접 고양 로테이션이며, 용암 폭발이나 마나 해일 토템을 배우기 전 모든 주술사의 기본값입니다. 원거리에서 번개 화살로 끌어온 뒤, 재사용 대기시간마다 폭풍의 일격, 소용돌이치는 무기 5중첩에서 즉시 시전 번개 화살, 적이 셋 이상이면 불꽃 회오리(불 토템이 세워져 있을 때)와 화염 충격, 폭풍의 일격 약화 효과에 맞춰 대지 충격, 그룹에서 화염 충격, 재사용 대기시간마다 대지 충격을 사용하며, 대상이 사거리 밖에 있는 동안에는 번개 화살로 빈틈을 채웁니다. Forever에서는 생명력과 마나가 애드온에 숨겨져 있으므로 스스로 치유하는 것과 마나 회복을 위해 멈추는 것은 직접 판단합니다(Wowhead 기본 제공 로테이션은 대신 마나를 아낍니다). 알림: 무기 강화(질풍의 무기, 없으면 불꽃의 무기, 없으면 대지의 무기), 물의 보호막 또는 번개 보호막, 대지 충격 차단, 불타는 토템 또는 용암 토템, 그룹 토템, 선견자의 분노, 돌발톱 토템. 직접 판단할 것: 토템 프리셋, 냉기 충격, 정화, 다른 토템."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "고양, 마나 효율 (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Wowhead와 Mobalytics의 마나 절약형 고양 로테이션입니다: 자동 공격이 주력이고, 폭풍의 일격은 폭풍의 일격 연마의 마나 회복 효과가 없을 때만 사용하며, 로테이션에 대지 충격이 없고(충격은 끌어오기와 차단용), 그룹이나 다수의 적을 상대할 때는 불타는 토템과 함께 재사용 대기시간마다 불꽃 회오리를 사용합니다. 무기 강화, 보호막, 차단 알림은 Icy Veins 기본 제공 로테이션과 같습니다. 마나가 바닥난다면 그 기본 제공 로테이션 대신 이것을 선택하세요. 추천 고양 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
L["rm.forever.shaman.restoration.Name"] = "복원"
L["rm.forever.shaman.restoration.Description"] = "복원이 주 특성 트리이고 16포인트(마나 해일 토템 계층)를 투자한 뒤의 치유 로테이션으로, Icy Veins를 따릅니다. 우호적 대상이 있으면: 자연의 신속함을 사용한 뒤 즉시 시전 치유의 물결, 해독과 질병 치료, 성난 해일이 없는 대상에게 성난 해일, 그룹에서는 연쇄 치유, 치유의 물결. 치유할 대상은 직접 대상으로 지정해 고릅니다. Forever에서는 생명력과 마나가 애드온에 숨겨져 있으므로 자연의 신속함과 하급 치유의 물결을 언제 쓸지는 직접 판단합니다. 적대적 대상이 있고 치유할 대상이 없으면: 다수의 적에게 불꽃 회오리와 연쇄 번개, 폭풍의 일격을 알면 폭풍의 일격과 대지 충격, 정예와 우두머리에게 화염 충격, 번개 화살, 그다음 근접 공격. 알림: 물의 보호막, 대지 충격 차단, 마나 해일 토템, 그룹 강화 토템. 직접 판단할 것: 하위 등급 사용, 다른 토템, 정화, 늑대 정령."
L["rm.mop.shaman.elemental.Name"] = "추천"
L["rm.mop.shaman.elemental.Description"] = "10레벨부터 정기에게 권장하며, 정기 전문화에서 언제나 선택됩니다. Wowhead의 순서입니다: 시작은 번개 화살(격노 폭발이 있으면 용암 폭발), 격노 폭발이 있으면 정기 폭발, 오래 살아남을 대상에게 화염 충격이 없거나 곧 끝나면 화염 충격, 화염 충격에 맞춰 용암 폭발(그리고 용암 쇄도마다), 정기 작렬, 화염 충격이 6초 남아 있는 동안 번개 보호막 충전 6회에서 대지 충격, 적이 둘이면 연쇄 번개, 번개 화살. 적이 넷 이상 나를 공격하면: 근접 거리에서 용암 토템, 무료 용암 폭발, 지배력 중 용암 광선, 연쇄 번개. 이동 중에는 즉시 시전 주문만 표시합니다. 알림: 번개 보호막, 불꽃의 무기, 불타는 토템, 정예와 우두머리에게 불의 정령 토템, 정기의 깨달음, 용암 폭발 뒤 지배력, 고대의 신속함, 그룹에서 폭풍채찍 토템과 피의 욕망, 날카로운 바람, 마나를 위한 천둥폭풍, 생명력이 낮으면 주술의 분노와 영혼 이동. 지진과 대지의 정령 토템은 나열되지만 꺼져 있습니다. 직접 판단할 것: 영혼나그네의 은총, 추가 대상의 화염 충격, 서 있을 위치."
L["rm.mop.shaman.enhancement.Name"] = "추천"
L["rm.mop.shaman.enhancement.Description"] = "10레벨부터 고양에게 권장하며, 고양 전문화에서 언제나 선택됩니다. Wowhead의 순서입니다: 달려가는 동안 정기 폭발, 그다음 격노 폭발이 있으면 정기 폭발, 소용돌이치는 무기 5중첩에서 정기 작렬과 번개 화살(또는 다음 자동 공격까지 1초 넘게 남았으면 3중첩에서 끼워 넣기), 지배력 중 번개폭풍, 폭풍의 일격(26레벨 전에는 원시의 일격), 용암 채찍, 불꽃 폭발 중 화염 충격, 정기 폭발, 대지 충격. 적이 둘 이상 나를 공격하면: 번개 화살 대신 연쇄 번개, 화염 충격을 퍼뜨리는 용암 채찍, 넷부터 불꽃 회오리, 여섯부터 용암 토템. 알림: 번개 보호막, 주 무기에 질풍의 무기와 보조 무기에 불꽃의 무기, 불타는 토템, 불의 정령 토템, 야수 정령, 폭풍의 일격 뒤 지배력, 정기의 깨달음, 고대의 신속함, 그룹에서 폭풍채찍 토템과 피의 욕망, 날카로운 바람, 생명력이 낮으면 주술의 분노와 영혼 이동. 대지의 정령 토템은 나열되지만 꺼져 있습니다."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "용암 채찍 우선 (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "기본적으로 꺼져 있습니다. 권장 고양 기본 제공 로테이션과 같은 전환 조건을 쓰므로, 사용하려면 이것을 켜고 그것을 끄세요. Icy Veins의 순서입니다: 폭풍의 일격, 그다음 소용돌이치는 무기를 쓰기 전에 용암 채찍, 5중첩에서 또는 다음 자동 공격 전에 적중하면 3중첩부터 번개 화살, 정기 폭발 후 화염 충격, 대지 충격. 적이 넷 이상이면 용암 채찍으로 화염 충격을 퍼뜨리고 불꽃 회오리를 사용하며, 무리에는 번개 화살 대신 연쇄 번개를 사용합니다. 주술의 분노는 전투 중 재사용 대기시간마다 제안하며, 그 외의 알림은 권장 기본 제공 로테이션과 같습니다."
L["rm.mop.shaman.enhancement.simulator.Name"] = "매 중첩 끼워 넣기 (시뮬레이터)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "기본적으로 꺼져 있습니다. 권장 고양 기본 제공 로테이션과 같은 전환 조건을 쓰므로, 사용하려면 이것을 켜고 그것을 끄세요. 자동 공격 사이에 시전 타이밍을 맞추는 플레이어를 위한 시뮬레이터 목록입니다: 다음 주 무기 자동 공격 전에 시전이 끝나면 소용돌이치는 무기 중첩 수와 관계없이 번개 화살, 정기 작렬 또는 연쇄 번개, 화염 충격이 없을 때마다 정기 폭발도 사용하며, 대지 충격은 2중첩 미만일 때만 사용합니다. 알림은 권장 기본 제공 로테이션과 같습니다."
L["rm.mop.shaman.restoration.Name"] = "추천"
L["rm.mop.shaman.restoration.Description"] = "10레벨부터 복원에게 권장하며, 복원 전문화에서 언제나 선택됩니다. 우호적 대상을 치유합니다(Rotation Master는 누구를 치유할지 고를 수 없음): 고대의 신속함 중 상급 치유의 물결, 35% 미만이면 치유의 파도, 마법이나 저주에 영혼 정화, 근처 아군 셋이 다쳤으면 정기 폭발 후 치유의 비, 성난 해일, 그룹 피해에 연쇄 치유, 60% 미만이면 상급 치유의 물결, 90% 미만이면 치유의 물결. 공격 가능한 대상이 있으면 대신 피해를 줍니다(화염 충격, 용암 폭발, 정기 작렬, 번개 화살). 알림: 물의 보호막, 대지생명의 무기, 주시 대상에게 대지의 보호막, 누군가 다쳤으면 치유의 토템, 마나 해일 토템, 큰 그룹 피해에 치유의 해일 토템, 정기의 깨달음 또는 고대의 인도, 생명력이 낮은 대상에게 고대의 신속함, 이동 중 영혼나그네의 은총, 피의 욕망, 날카로운 바람. 지배력과 정신의 고리 토템은 나열되지만 꺼져 있습니다: 공격대에서 배정받으면 사용하세요."
L["rm.mop.shaman.restoration.hekili.Name"] = "생명력 단계별 (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "기본적으로 꺼져 있습니다. 권장 복원 기본 제공 로테이션과 같은 전환 조건을 쓰므로, 사용하려면 이것을 켜고 그것을 끄세요. Hekili의 목록은 대상에게 대지의 보호막과 성난 해일을 유지하고, 치유의 토템과 치유의 비가 꺼져 있으면 언제든 다시 쓴 뒤, 40미터 이내 그룹의 평균 생명력에 따라 치유합니다: 80% 미만이면 연쇄 치유, 70% 미만인 대상에게 치유의 물결, 60% 미만이면 상급 치유의 물결, 40% 미만이면 치유의 파도이며, 치유의 해일 토템, 고대의 인도, 마나 해일 토템도 같은 단계에 있습니다. 공격 가능한 대상에게는 피해 기술과 대지 충격을 사용합니다."
L["rm.mop.shaman.unspecialized.Name"] = "전문화 없음"
L["rm.mop.shaman.unspecialized.Description"] = "1–9레벨과 아직 전문화를 고르지 않은 주술사용이며, 전문화를 고르면 각 전문화 기본 제공 로테이션이 넘겨받습니다. 원거리에서 번개 화살로 끌어오고, 혼자이면서 생명력이 낮으면 치유의 파도, 원시의 일격, 대지 충격, 근접 거리 밖에서는 번개 화살을 사용합니다. 번개 보호막을 유지합니다."
L["rm.retail.shaman.elemental.Name"] = "Blizzard 전투 보조"
L["rm.retail.shaman.elemental.Description"] = "한밤에서 정기 전문화에 권장됩니다. 이제 게임이 전투 중 화염 충격, 강화 효과, 소용돌이, 재사용 대기시간, 생명력을 애드온에 숨기므로, 이 로테이션은 Blizzard의 자체 전투 보조 제안(원버튼 로테이션)을 보여 주며, 시전 중이거나 적을 대상으로 지정하지 않았을 때는 멈춥니다. 제안에서 빠진 것에 대한 알림: 전투 중 승천, 불의 정령 또는 폭풍의 정령, 자연의 신속함, 이동 중 영혼나그네의 은총, 전투 사이에 번개 보호막과 하늘의 격노(Blizzard의 제안은 무기 강화와 보호막 강화를 유지합니다), 차단 가능한 시전에 날카로운 바람(게임이 시전을 읽도록 허용하는 곳에서만 강조됩니다), 전투 중 준비될 때마다 영혼 이동(Retail에서는 생명력이 숨겨지므로 언제 쓸지는 직접 판단합니다)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "참고용 (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins와 SimulationCraft의 순서는 화염 충격, 원소의 대가, 폭풍수호자를 읽는데, 한밤은 이를 전투 중 숨기며, Retail에서는 소용돌이가 숨겨지므로 소모 기술은 소용돌이가 거의 가득 찰 때가 아니라 비용만큼 쌓였을 때 사용합니다. 전투 전에 폭풍수호자와 용암 폭발. 교전 중인 적이 셋 이상일 때: 폭풍수호자, 선조의 신속함, 화염 충격, 폭풍수호자가 있을 때 연쇄 번개, 정기 작렬, 지진, 용암 쇄도 발동 시 용암 폭발, 폭풍, 연쇄 번개. 그 외에는 폭풍수호자, 선조의 신속함, 원소의 대가 밖에서 남은 시간이 30% 이하일 때 화염 충격과 전격의 불길, 원소의 대가를 시작하기 위해 용암 폭발, 원소의 대가 중 폭풍과 폭풍수호자 번개 화살, 원소의 대가 중 정기 작렬 또는 대지 충격, 전격의 불길, 폭풍, 이동 중 화염 충격 또는 냉기 충격, 쓸 수 있을 때마다 정기 작렬 또는 대지 충격, 번개 화살. 알림: 폭풍수호자를 쓴 뒤 승천, 정령, 영혼나그네의 은총, 그리고 공용 알림."
L["rm.retail.shaman.enhancement.Name"] = "Blizzard 전투 보조"
L["rm.retail.shaman.enhancement.Description"] = "한밤에서 고양 전문화에 권장됩니다. Blizzard의 전투 보조 제안을 보여 주며(소용돌이치는 무기를 소모하고, 화염 충격을 유지하며, 쇄도하는 토템과 세계의 분리를 처리합니다), 시전 중이거나 적을 대상으로 지정하지 않았을 때는 멈춥니다. 제안에서 빠진 것에 대한 알림: 전투 중 승천, 파멸의 바람, 야수 정령, 전투 사이에 번개 보호막과 하늘의 격노(Blizzard의 제안은 질풍의 무기를 유지합니다), 날카로운 바람, 영혼 이동."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "폭풍인도자 참고용 (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "참고용이며 기본적으로 꺼져 있습니다. SimulationCraft의 폭풍인도자 목록(Icy Veins와 Wowhead도 동의)은 화염 충격, 낙뢰, 채찍 화염, 재사용 대기시간 타이머를 읽는데, 한밤은 이를 전투 중 숨깁니다. 교전 중인 적이 셋 이상일 때: 강화 효과를 위해 낙뢰, 소용돌이치는 무기 10중첩에서 폭풍, 9중첩에서 연쇄 번개, 낙뢰, 용암 채찍, 세계의 분리. 그다음 9중첩에서 태고의 폭풍, 화염 충격이 없으면 전격의 불길 또는 화염 충격, 세계의 분리, 강화 효과를 위해 낙뢰, 채찍 화염을 위해 용암 채찍, 바람의 일격, 10중첩에서 폭풍 또는 번개 화살(전격의 불길이나 낙뢰가 곧 준비되면 8중첩), 충전 2회에서 폭풍의 일격, 용암 채찍, 폭풍의 일격, 전격의 불길, 낙뢰, 5중첩에서 번개 화살, 화염 충격. 알림: 파멸의 바람, 파멸의 바람 밖에서 승천, 야수 정령, 그리고 공용 알림."
L["rm.retail.shaman.enhancement.totemic.Name"] = "토템술사 참고용 (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "참고용이며 기본적으로 꺼져 있습니다. SimulationCraft의 토템술사 목록은 화염 충격, 뜨거운 손, 소용돌이치는 불, 낙뢰, 파멸의 바람을 읽는데, 한밤은 이를 전투 중 숨깁니다. 교전 중인 적이 셋 이상일 때: 낙뢰, 소용돌이치는 무기 5중첩에서 연쇄 번개. 그다음 화염 충격이 없으면 전격의 불길 또는 화염 충격, 쇄도하는 토템, 세계의 분리, 뜨거운 손이나 소용돌이치는 불이 있을 때 용암 채찍, 강화 효과를 위해 낙뢰, 10중첩에서 태고의 폭풍, 바람의 일격, 파멸의 바람 중 낙뢰와 폭풍의 일격, 5중첩에서 번개 화살, 낙뢰, 용암 채찍, 폭풍의 일격, 전격의 불길, 화염 충격. 알림은 폭풍인도자 참고용 로테이션과 같습니다."
L["rm.retail.shaman.initial.Name"] = "Blizzard 전투 보조"
L["rm.retail.shaman.initial.Description"] = "전문화를 선택하기 전(게임이 주술사의 초기 전문화를 보고하는 동안)에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 모든 주술사 기본 제공 로테이션이 공유하는 알림을, 해당 주문을 배운 뒤에 각각 제공합니다. 10레벨에 전문화를 선택하면 해당 전문화의 기본 제공 로테이션이 대신합니다."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "한밤에서의 복원, 참고용: Blizzard의 전투 보조는 치유 전담을 다루지 않고, 게임은 전투 중 모든 사람의 생명력을 숨기며, Rotation Master는 대상이 아니라 주문을 고르므로, 이 로테이션은 대상으로 지정한 누구에게든 준비된 순서대로 치유 기술을 정렬하고 누구를 치유할지는 직접 판단합니다. 우호적 대상에게: 치유의 토템, 생명 폭발, 그룹에서 치유의 비, 쇄도하는 토템, 성난 해일, 그룹에서 연쇄 치유, 치유의 물결. 적에게: 화염 충격이 없으면 화염 충격, 용암 폭발, 번개 화살. 알림: 전투 사이에 물의 보호막, 우호적 대상에게 대지의 보호막, 하늘의 격노; 전투 중 자연의 신속함; 그룹 전투 중 치유의 해일 토템과 정신의 고리 토템; 날카로운 바람; 영혼 이동."
L["rm.sod.shaman.elemental.Name"] = "정기 (SoD)"
L["rm.sod.shaman.elemental.Description"] = "10레벨부터의 디스커버리 시즌 정기 로테이션(정기에 특성 점수가 가장 많을 때)으로, 시뮬레이터 6단계, Wowhead, Icy Veins를 바탕으로 만들었습니다. 대지 충격으로 차단합니다. 이동 중에는: 화염 충격, 번개 보호막 충전 8회에서 대지 충격, 마력의 쇄도 발동 시 용암 폭발 또는 연쇄 번개. 적이 셋 이상이면: 화염 충격, 연쇄 번개, 불꽃 회오리, 용암 폭발, 충전 8회에서 대지 충격, 용암 토템. 그다음 마력의 쇄도에 용암 폭발, 화염 충격 유지, 내 화염 충격이 지속되는 동안 용암 폭발, 충전 8회에서 대지 충격, 적이 둘이면 연쇄 번개, 번개 화살. 알림: 태우기를 위한 불꽃의 무기, 번개 보호막, 자신에게 대지의 보호막, 우두머리의 영혼, 야수 정령, 주술의 분노, 정기의 깨달음, 토템. 장신구, 토템 재배치, 해제, 정화는 직접 판단합니다."
L["rm.sod.shaman.enhancement.Name"] = "고양 (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "디스커버리 시즌 1–60레벨용이며 룬은 새긴 대로 사용하고, 쌍수든 양손 무기든 상관없으며, 다른 기본 제공 로테이션이 맞지 않는 모든 디스커버리 시즌 주술사용입니다. 시뮬레이터 6단계, Icy Veins, Wowhead를 바탕으로 만들었습니다. 화염 충격으로 끌어오고, 대지 충격으로 차단합니다. 적이 셋 이상이면: 용암 토템, 화염 토템에서 불꽃 회오리, 소용돌이치는 무기 4중첩에서 연쇄 번개, 화염 충격. 그다음 소용돌이치는 무기 5중첩에서 용암 폭발, 폭풍의 일격, 용암 채찍, 5중첩에서 번개 화살, 지속될 때 화염 충격, 대지 충격, 용암 작열, 원거리에서 번개 화살. 알림: 질풍의 무기(그 전에는 대지의 무기), 용암 채찍이 있으면 보조 무기에 불꽃의 무기(없으면 질풍의 무기; 방패에는 절대 걸지 않음; 양손 모두 질풍의 무기를 쓰는 Icy Veins 줄은 꺼진 상태로 나열), 물의 보호막 또는 번개 보호막, 우두머리의 영혼, 야수 정령, 마나 65% 미만에서 주술의 분노, 토템, 고대의 인도. 토템 재배치, 해제, 정화는 직접 판단합니다."
L["rm.sod.shaman.restoration.Name"] = "회복 (SoD)"
L["rm.sod.shaman.restoration.Description"] = "10레벨부터의 디스커버리 시즌 복원 로테이션(복원에 특성 점수가 가장 많을 때)으로, Icy Veins와 Wowhead를 바탕으로 만들었습니다. 우호적 대상에게: 40% 미만이면 성난 해일 후 하급 치유의 물결, 해독 또는 질병 치료, 근처 그룹원 셋이 85% 미만이면 치유의 비, 둘이면 연쇄 치유(마력의 쇄도 발동 시 즉시), 굽이치는 물결을 위해 95% 미만에서 성난 해일, 90% 미만이면 치유의 물결. 싸우는 적에게도 작동합니다. 알림: 물의 보호막(그 전에는 번개 보호막), 우호적 대상이나 자신에게 대지의 보호막, 주술의 분노, 마나 해일 토템, 마나샘 토템, 대지력 토템. 누구를 치유할지와 진동의 토템이나 정화 토템은 직접 판단합니다."
L["rm.sod.shaman.tank.Name"] = "방어 전담 (SoD, 대지의 길)"
L["rm.sod.shaman.tank.Description"] = "디스커버리 시즌 방어 전담 로테이션으로, 대지의 길을 새겼을 때 선택됩니다. Icy Veins, Wowhead, 시뮬레이터, Warcraft Tavern을 바탕으로 만들었습니다. 화염 충격으로 끌어옵니다. 대지 충격으로 나를 공격하지 않는 근접 거리의 대상을 도발하고, 차단합니다. 적이 둘 이상이면: 용암 작열, 화염 충격, 소용돌이치는 무기 5중첩이나 마력의 쇄도에 연쇄 번개, 5중첩에서 불꽃 회오리. 그다음 화염 충격 유지, 마력의 쇄도에 또는 화염 충격이 지속되는 동안 용암 폭발, 폭풍의 일격, 대지 충격, 5중첩에서 번개 화살, 용암 작열, 냉기 충격. 알림: 대지의 무기, 번개 보호막, 자신에게 우두머리의 영혼, 야수 정령, 주술의 분노, 불타는 토템 또는 용암 토템, 그룹 토템."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "정기 (Icy Veins & 시뮬레이터)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "정기 특성 트리를 위한 시전형 정기 로테이션입니다. 번개 화살이 기본 주문이고, 연쇄 번개는 정기의 깨달음과 함께, 마나가 40% 이상일 때 정신 집중 발동 시, 또는 마나 80% 이상이면 자유롭게 사용합니다. 화염 충격은 이동 중에만, 대지 충격은 차단용, 다수의 적에게는 불꽃 회오리, 연쇄 번개, 용암 토템을 사용합니다. 연쇄 번개 전에 근접 거리의 대상은 마나를 아끼기 위해 자동 공격에 맡깁니다. 알림: 물의 보호막 또는 번개 보호막, 무기 강화, 격노의 토템(긴 전투에서는 불타는 토템), 천벌의 토템, 마나샘 토템, 전투 후 토템의 부름, 정기의 깨달음, 피의 욕망/영웅심."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "정기 (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "NextActionTBC의 정기 로테이션으로, 추천 Icy Veins 정기 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 대상에게 화염 충격을 유지하고, 연쇄 번개는 적이 둘 이상이고 마나가 30% 이상일 때만, 그 외에는 번개 화살을 사용합니다. 번개 보호막, 무기 강화, 정기의 깨달음, 피의 욕망/영웅심을 알려 주며, 토템은 직접 관리합니다."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "정기 (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "Wowhead의 정기 로테이션으로, 추천 Icy Veins 정기 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 70레벨에서는 재사용 대기시간마다 연쇄 번개를 쓰고 그 사이에 번개 화살을 사용합니다(레벨업 중에는 정기의 깨달음이나 정신 집중이 있을 때만). 화염 충격은 이동 중에만, 대지 충격은 시전이 끝나기 전에 죽을 대상을 마무리할 때 사용합니다. 토템, 보호막, 재사용 대기시간 알림은 Icy Veins 변형과 같습니다."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "고양 (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "1레벨부터 70레벨까지의 근접 고양 로테이션이며, 다른 기본 제공 로테이션이 맞지 않는 모든 주술사의 기본값입니다. 원거리에서 번개 화살로 끌어오고, 대지 충격으로 차단하며, 근처에 적이 셋 이상이면 불꽃 회오리 토템과 용암 토템을 세운 뒤 폭풍의 일격, 폭풍의 일격 약화 효과가 있는 동안 대지 충격, 오래 살아남을 대상에게 화염 충격, 재사용 대기시간마다 대지 충격을 사용하고, 대상이 사거리 밖에 있는 동안에는 번개 화살을 사용합니다. 별도 알림: 무기 강화, 물의 보호막 또는 번개 보호막, 대지력 토템, 질풍의 토템(그룹) 또는 은총의 토템(혼자), 긴 전투의 불타는 토템, 물 토템, 주술의 분노, 우두머리 상대 피의 욕망/영웅심, 혼자일 때 돌발톱 토템과 대지의 정령 토템. 불의 정령 토템은 꺼진 상태로 시작하는 선택 단계입니다. 토템 배치, 늑대 정령, 치유는 직접 판단합니다."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "고양 (Wowhead & 시뮬레이터)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "70레벨 공격대용 토템 교체(트위스팅) 모델로, 추천 Icy Veins 고양 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 폭풍의 일격, 불꽃 회오리 토템 끼워 넣기, 화염 충격이 사라질 때마다 다시 걸기, 주력 충격으로 대지 충격을 사용하며, 번개 화살은 사거리 밖에서만 사용합니다. 알림은 질풍의 토템과 은총의 토템을 교체(트위스팅)하고, 불타는 토템을 유지하며, 마나가 부족하면 주술의 분노를 사용하고, 무기 강화·보호막·토템 유지 관리는 Icy Veins 변형과 공유합니다."
L["rm.tbc.shaman.restoration.Name"] = "복원"
L["rm.tbc.shaman.restoration.Description"] = "복원 특성 트리를 위한 치유 로테이션으로, 우호적 대상(대상이 없으면 자신)에게 사용합니다: 위급할 때 자연의 신속함과 치유의 물결 또는 하급 치유의 물결, 해독과 질병 치료, 주시 대상에게 대지의 보호막, 근처 아군 셋이 피해를 입었으면 연쇄 치유, 그 외에는 치유의 물결. 적대적 대상이 있으면 혼자 사냥을 위해 화염 충격과 번개 화살로 전환합니다. 알림: 물의 보호막, 주시 대상에게 대지의 보호막(방어 전담을 주시 대상으로 지정하세요), 마나 해일 토템, 그룹에서 마나샘 토템과 대지력 토템, 피의 욕망/영웅심. 누구를 치유할지와 어떤 등급을 쓸지는 직접 판단합니다."
